package io.github.dawnseek.autotable.core.utils;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

import io.github.dawnseek.autotable.core.exception.TableCreateException;

/**
 * Description: database util
 *
 * @author dawnseek
 * @version 2025/3/12
 */
public class DbUtil {
    /**
     * allowed leading keywords of a statement generated by this component
     */
    private static final Set<String> ALLOWED_KEYWORDS = new HashSet<>(Arrays.asList("CREATE", "ALTER", "COMMENT"));

    /**
     * validate sql generated by this component before executing it.
     * Only the leading keyword is checked so that legitimate statement bodies
     * (e.g. a trigger body containing UPDATE/DELETE FROM) are never altered.
     * @param sql sql to validate
     * @return the original sql when it is safe
     */
    public static String safeSql(String sql) {
        if (StringUtil.isBlank(sql)) {
            throw new TableCreateException("sql is blank");
        }
        String firstKeyword = sql.trim().split("\\s+", 2)[0].toUpperCase();
        if (!ALLOWED_KEYWORDS.contains(firstKeyword)) {
            throw new TableCreateException(String.format("unsafe sql statement rejected: %s", firstKeyword));
        }
        return sql;
    }
}
